        self.sender = sender
        self.receiver = receiver
        self.amount = amount
        self.timestamp = timestamp

    def to_dict(self):
        return {
            "sender": self.sender,
            "receiver": self.receiver,
            "amount": self.amount,
            "timestamp": self.timestamp,
        }

